L(OA, 3,
  "Aprenderé a asegurar la coherencia y la cohesión del texto: organización oracional y textual, y uso de conectores para unir secciones y relacionar ideas dentro de cada párrafo.",
  ["Organizo ideas en categorías.", "Conozco conectores básicos."],
  ["La coherencia es la unidad de sentido: el texto trata un tema central y todas sus partes se relacionan con él. La cohesión es la unión gramatical entre oraciones y párrafos: se logra con conectores, pronombres, sinónimos y repeticiones. Un texto puede tener cohesión sin coherencia, si usa conectores pero dice cosas sin relación.",
   "Los conectores señalan relaciones: adición (además, también), contraste (sin embargo, en cambio), causa (porque, ya que), consecuencia (por eso, así que), orden (primero, luego, finalmente), ejemplo (por ejemplo), conclusión (en síntesis). Dentro de un párrafo relacionan ideas; entre párrafos unen secciones («Una segunda razón es…», «Para terminar…»).",
   "En el plano oracional, una oración bien organizada tiene sujeto, verbo y complementos en un orden claro y no es demasiado larga. En el plano textual, los párrafos siguen un orden lógico: introducción, desarrollo, cierre. Para revisar, lee las oraciones iniciales de cada párrafo: deben formar un hilo."],
  [("coherencia", "unidad de sentido del texto"), ("cohesión", "unión gramatical entre las partes del texto"), ("conector", "palabra que une ideas y muestra su relación"), ("oración compleja", "oración con más de un verbo conjugado")],
  [("Elegir el conector",
    "«El museo tiene entrada gratuita; ____, muchos estudiantes lo visitan». ¿Qué conector expresa consecuencia?",
    ["La gratuidad provoca la visita.", "Es consecuencia.", "Va «por eso»."],
    "«Por eso»"),
   ("Coherencia sin cohesión",
    "Texto: «El huerto crece. Los autos son rápidos. Mi tía vive lejos». ¿Tiene coherencia?",
    ["Las tres ideas no se relacionan.", "Falta tema central.", "No tiene coherencia."],
    "No, las ideas no se relacionan con un tema central")],
  [("Usar solo «y» para unir todo.", "No se muestran las relaciones.", "Elige el conector según la relación."),
   ("Poner conectores sin que las ideas se relacionen.", "Se aparenta un hilo que no existe.", "Primero asegura el sentido.")],
  ([E("¿En el cuaderno de Lengua y Literatura de 1.º medio, qué es la coherencia?", "La unidad de sentido del texto", "Todo gira en torno a un tema."),
    E("¿En el cuaderno de Lengua y Literatura de 1.º medio, qué es la cohesión?", "La unión gramatical entre las partes", "Se logra con conectores y pronombres."),
    E("¿«Sin embargo» expresa contraste o causa?", "Contraste", "Opone dos ideas distintas.")],
   [E("Completa: «Estudié mucho; ____, aprobé la prueba». A) por eso B) sin embargo", "A) por eso", "Estudiar causa el resultado."),
    E("Completa: «Quería salir; ____, tenía que terminar la tarea». A) sin embargo B) además", "A) sin embargo", "Hay un contraste entre ideas."),
    E("¿Qué conector sirve para dar un ejemplo? A) por ejemplo B) por eso", "A) por ejemplo", "Introduce un caso concreto.")],
   [E("Ordena con conectores: (1) finalmente, (2) en primer lugar, (3) luego. Escribe los números en orden.", "2, 3, 1", "Marcan el orden de la serie."),
    E("¿Qué conector abre una conclusión? A) en síntesis B) por otro lado", "A) en síntesis", "Resume lo dicho."),
    E("Texto: «Hay poca luz. Además, el aula es fría». ¿Qué relación hay? A) adición B) contraste", "A) adición", "«Además» suma otro problema.")],
   [E("Un párrafo une cinco oraciones solo con «y». ¿Qué problema hay? A) no se muestran causas ni contrastes entre las ideas B) las oraciones son demasiado cortas", "A) no se muestran causas ni contrastes entre las ideas", "Todos los enlaces son iguales y no señalan la relación."),
    E("Un texto está lleno de conectores pero habla de temas distintos en cada oración. ¿Tiene coherencia?", "No", "Falta tema central.")],
   [E("Un ensayo tiene 6 párrafos y quieres un conector que una cada par consecutivo. ¿Cuántos conectores entre párrafos necesitas?", "5", "Hay cinco uniones entre seis párrafos.", "6 - 1"),
    E("Elige la oración más claramente organizada. A) «Los estudiantes que llegan tarde pierden la primera clase» B) «Pierden la primera clase que llegan tarde los estudiantes»", "A) «Los estudiantes que llegan tarde pierden la primera clase»", "Tiene orden claro: sujeto, verbo y complemento; en la B el orden confunde qué es lo que se pierde.")]),
  [E("Primeras oraciones de tres párrafos: «La biblioteca es útil.» «Una razón es su silencio.» «Otra razón es su horario.» ¿Forman un hilo? A) sí B) no", "A) sí", "Todas desarrollan la utilidad de la biblioteca.")],
  [E("¿Qué une párrafos?", "Los conectores", "Señalan relaciones entre secciones."),
   E("¿Qué es una oración bien organizada?", "La que tiene un orden claro", "Se entiende sin esfuerzo."),
   E("¿Se puede tener cohesión sin coherencia?", "Sí", "Con conectores pero sin sentido global.")],
  ("Une estas ideas en un párrafo de cuatro oraciones sobre la biblioteca usando al menos tres conectores de distinto tipo: «hay silencio», «el horario es amplio», «algunos libros están viejos», «se necesita comprar libros nuevos».",
   "La biblioteca es un buen lugar para estudiar. Hay silencio y, además, el horario es amplio. Sin embargo, algunos libros están viejos. Por eso, se necesita comprar libros nuevos.",
   ["al menos tres conectores", "de distinto tipo", "mantiene coherencia"], ["párrafo de cuatro oraciones"], ["repetir el mismo conector"], "Subraya los conectores y comprueba que sean de tipos distintos."),
  "Lee un párrafo tuyo y subraya los conectores.",
  "Escribe cinco oraciones con cinco conectores distintos.")

# ------------------------------------------------------------------ OA 15 · clase 4
L(OA, 4,
  "Aprenderé a escribir un primer desarrollo con vocabulario variado y preciso, evitando palabras comodín y repeticiones.",
  ["Aseguro coherencia y cohesión.", "Distingo sinónimos."],
  ["Un vocabulario variado usa distintas palabras para no repetir sin necesidad. Uno preciso elige la palabra que nombra exactamente lo que se quiere decir. Las palabras comodín, como «cosa», «hacer», «tener» o «bueno», sirven para todo y por eso dicen poco. «Hicimos una cosa buena» es vago; «organizamos una colecta solidaria» es preciso.",
   "Para mejorar la precisión, se buscan verbos más específicos («elaborar», «construir», «redactar» en vez de «hacer»), sustantivos concretos («colecta» en vez de «cosa») y adjetivos que informan («útil», «puntual»). También se usan sinónimos y términos técnicos cuando el género lo permite. Un diccionario de sinónimos y uno de la lengua ayudan, pero hay que revisar que el sinónimo calce con el contexto.",
   "Ojo con las palabras que parecen sinónimos pero cambian el sentido: «grande» y «gran» no siempre se intercambian; «ver» y «mirar» no son iguales. La repetición intencionada de una palabra clave puede ser un recurso de cohesión; la repetición descuidada, no."],
  [("palabra comodín", "palabra muy general que sirve para casi todo, como cosa o hacer"), ("vocabulario preciso", "uso de la palabra exacta para lo que se quiere decir"), ("sinónimo", "palabra de significado parecido a otra"), ("repetición descuidada", "repetición sin intención que empobrece el texto")],
  [("Reemplazar una palabra comodín",
    "Oración: «Hicimos un informe sobre el reciclaje». Mejora el verbo «hicimos».",
    ["«Hicimos» es muy general.", "Un informe se redacta.", "Uso «redactamos»."],
    "Redactamos un informe sobre el reciclaje"),
   ("Precisar un sustantivo",
    "Oración: «Compramos varias cosas para la feria». Si las cosas son cartulinas, plumones y cinta, ¿cómo mejoras?",
    ["«Cosas» no dice qué son.", "Nombro los materiales.", "Gano precisión."],
    "Compramos cartulinas, plumones y cinta para la feria")],
  [("Repetir «cosa» y «hacer» en todo el texto.", "El texto se vuelve vago.", "Busca el verbo y el sustantivo específicos."),
   ("Cambiar una palabra por un sinónimo sin revisar el sentido.", "Puede cambiar el significado.", "Comprueba que calce con el contexto.")],
  ([E("¿Qué es una palabra comodín?", "Una palabra muy general que sirve para casi todo", "Dice muy poco."),
    E("¿«Redactar» es más preciso que «hacer» al hablar de un informe: sí o no?", "Sí", "Nombra la acción exacta."),
    E("¿Un diccionario de sinónimos ayuda a variar el vocabulario: sí o no?", "Sí", "Ofrece alternativas a una palabra.")],
   [E("Mejora «Tengo una cosa buena para el curso». ¿Cuál es más preciso? A) «Tengo una propuesta valiosa para el curso» B) «Tengo algo bueno para el curso»", "A) «Tengo una propuesta valiosa para el curso»", "Nombra qué es y en qué es buena; «algo bueno» sigue siendo vago."),
    E("Reemplaza «hacer» en «hacer una maqueta». A) construir B) tener", "A) construir", "Es el verbo exacto para una maqueta."),
    E("¿Qué palabra es comodín? A) cosa B) microscopio", "A) cosa", "Puede referirse a cualquier objeto.")],
   [E("Oración: «La profesora dijo que el trabajo era grupal y dijo que se entregaba el lunes». ¿Qué mejora de variedad conviene? A) cambiar el segundo «dijo» por «indicó» B) agregar otro «dijo»", "A) cambiar el segundo «dijo» por «indicó»", "Evita repetir el mismo verbo."),
    E("Clasifica cada palabra como P (precisa) o C (comodín): 1) cosa. 2) pizarra. 3) hacer. Escribe las letras en orden.", "C, P, C", "«Pizarra» nombra un objeto específico."),
    E("Para un informe formal, ¿qué verbo es más adecuado en lugar de «hablar»? A) exponer B) chacharear", "A) exponer", "Pertenece a un registro formal y es más preciso.")],
   [E("Un compañero cambia «ver» por «mirar» en «ver la tele» y dice que da igual. ¿Es siempre igual?", "No; «mirar» implica atención voluntaria", "El matiz cambia."),
    E("Un texto repite «importante» seis veces. ¿Qué haces? A) usar sinónimos que calcen con el contexto, como «esencial» o «relevante» B) dejar la palabra igual en todos los casos", "A) usar sinónimos que calcen con el contexto, como «esencial» o «relevante»", "Varía sin cambiar el sentido; repetir sin intención empobrece el texto.")],
   [E("Evalúa cada reemplazo de «hacer» como A (adecuado) o I (inadecuado): 1) hacer una maqueta → construir una maqueta. 2) hacer una pregunta → construir una pregunta. 3) hacer un resumen → elaborar un resumen. Escribe las letras en orden.", "A, I, A", "Se construye una maqueta y se elabora un resumen; una pregunta se formula, no se construye."),
    E("Reescribe con precisión: «Hay una cosa que hace que haya ruido». A) «Un parlante causa ruido» B) «Algo hace cosa»", "A) «Un parlante causa ruido»", "Reemplaza lo vago por una causa concreta.")]),
  [E("Oración: «Tenemos que hacer una cosa para ayudar». ¿Cuál es la versión más precisa? A) «Debemos organizar una colecta para ayudar» B) «Hay que hacer algo»", "A) «Debemos organizar una colecta para ayudar»", "Nombra una acción concreta.")],
  [E("¿Qué es un vocabulario preciso?", "Usar la palabra exacta", "Nombra lo que se quiere decir."),
   E("¿Se puede repetir una palabra clave?", "Sí, si es intencional", "Puede dar cohesión."),
   E("¿Qué se revisa al usar un sinónimo?", "Que calce con el contexto", "Evita cambiar el sentido.")],
  ("Reescribe este borrador de ejemplo cambiando las palabras comodín y las repeticiones: «Hicimos una cosa para la feria. Fue una cosa buena. Hicimos otra cosa que también fue buena». Entrega una versión de tres oraciones.",
   "Organizamos un puesto para la feria. Fue una iniciativa exitosa. Además, elaboramos un afiche que resultó atractivo.",
   ["reemplaza comodines", "varía los verbos", "mantiene el sentido"], ["versión de tres oraciones"], ["cambiar sin precisar"], "Subraya las palabras nuevas y comprueba que sean más específicas."),
  "Busca en un texto tres palabras comodín.",
  "Escribe diez verbos precisos que reemplacen «hacer».")

# ------------------------------------------------------------------ OA 15 · clase 5
L(OA, 5,
  "Aprenderé a reconocer y corregir usos inadecuados: pronombres personales y reflexivos, conjugaciones, participios irregulares, conectores y concordancia.",
  ["Uso vocabulario preciso.", "Conozco las partes de la oración."],
  ["Revisar la gramática es parte de reescribir. Los pronombres reflexivos (me, te, se, nos) deben coincidir con la persona del verbo: «yo me lavo», «tú te lavas», «nosotros nos fuimos». Errores como «tú se lavas» o «nosotros se fuimos» no concuerdan. Después de preposición, se usan «mí» y «ti» («para mí»), salvo con «entre» y «según»: «entre tú y yo», «según tú».",
   "Hay verbos irregulares que se conjugan de forma especial: «anduve» (no «andé»), «dijeron» (no «dijieron»), «quepo» (no «cabo»), «haya» (no «haiga»). El verbo «haber» en sentido de existir es impersonal y no cambia: «había muchos libros», «hubo problemas» (no «habían» ni «hubieron»). Los participios irregulares son: abierto, cubierto, dicho, escrito, hecho, muerto, puesto, resuelto, roto, visto, vuelto.",
   "La concordancia exige que las palabras coincidan en género y número: artículo con sustantivo («las ventanas»), sustantivo con adjetivo («niñas contentas»), sujeto con verbo («los resultados fueron claros»). Para detectarla, se subraya el sujeto y se pregunta si el verbo coincide en número. Un buen revisor lee en voz alta y confirma cada concordancia."],
  [("pronombre reflexivo", "pronombre que indica que la acción recae en quien la hace: me, te, se, nos"), ("participio irregular", "forma verbal terminada de manera especial, como roto o escrito"), ("concordancia", "coincidencia de género y número entre las palabras"), ("verbo impersonal", "verbo que no tiene sujeto personal, como «hubo»")],
  [("Corregir un reflexivo",
    "Oración: «Nosotros se fuimos temprano». Corrígela.",
    ["El sujeto es «nosotros».", "El reflexivo debe ser «nos».", "Queda «nos fuimos»."],
    "Nosotros nos fuimos temprano"),
   ("Corregir un participio",
    "Oración: «He rompido el lápiz». Corrígela.",
    ["«Romper» tiene participio irregular.", "Es «roto».", "Queda «he roto»."],
    "He roto el lápiz")],
  [("Decir «habían muchos problemas».", "«Haber» impersonal no se conjuga en plural.", "Usa «había» o «hubo»."),
   ("Formar participios regulares de verbos irregulares (rompido).", "Esos verbos tienen participio especial.", "Aprende la lista de participios irregulares.")],
  ([E("¿Cuál es el participio de «romper»: roto o rompido?", "Roto", "Es un participio irregular."),
    E("«Tú se lavas las manos». ¿Cuál es el reflexivo correcto: te o se?", "Te", "Con «tú» corresponde «te»."),
    E("¿Es correcto «Los niñas»: sí o no?", "No", "El artículo no concuerda con el sustantivo femenino.")],
   [E("Completa: «Hemos ____ el informe» (escribir). A) escrito B) escribido", "A) escrito", "«Escribir» tiene participio irregular."),
    E("Elige la forma correcta. A) «Ayer anduve mucho» B) «Ayer andé mucho»", "A) «Ayer anduve mucho»", "El pretérito de «andar» es «anduve»."),
    E("Elige la forma correcta. A) «Hubo problemas» B) «Hubieron problemas»", "A) «Hubo problemas»", "«Haber» impersonal no cambia de número.")],
   [E("Clasifica el error con P (participio), C (concordancia) o R (reflexivo): 1) «abrido». 2) «las problemas». 3) «yo se levanto». Escribe las letras en orden.", "P, C, R", "Cada error pertenece a un tipo distinto."),
    E("Elige la frase correcta. A) «Entre tú y yo no hay secretos» B) «Entre tú y mí no hay secretos»", "A) «Entre tú y yo no hay secretos»", "Con «entre» se usan los pronombres de sujeto."),
    E("Completa: «Ya he ____ los libros en la mesa» (poner). A) puesto B) ponido", "A) puesto", "El participio de «poner» es irregular.")],
   [E("Un compañero dice que «haiga» es correcto porque se escucha mucho. ¿Qué respondes?", "Que la forma estándar es «haya»", "En la lengua escrita se usa la forma estándar."),
    E("Oración: «Los resultados de la encuesta fue claros». ¿Qué falla? A) el verbo no concuerda con el sujeto plural B) falta un punto", "A) el verbo no concuerda con el sujeto plural", "Debe ser «fueron».")],
   [E("Oración: «Ya he escribido y abrido la carta». ¿Cuántos errores hay?", "2", "«Escribido» y «abrido» deben ser «escrito» y «abierto»."),
    E("Elige la corrección completa de «Ellos andó y dijieron la verdad». A) «Ellos anduvieron y dijeron la verdad» B) «Ellos andó y dijeron la verdad»", "A) «Ellos anduvieron y dijeron la verdad»", "Corrige la conjugación de ambos verbos.")]),
  [E("Párrafo con errores: «Hubieron cinco problemas en el laboratorio. Yo se lavé las manos al salir. La puerta está rompida». ¿Cuántos errores hay?", "3", "«Hubieron», «se lavé» y «rompida» son incorrectos.")],
  [E("¿En el cuaderno de Lengua y Literatura de 1.º medio, cuál es el participio de «escribir»?", "Escrito", "Es un participio irregular."),
   E("¿«Había muchos libros» es correcto?", "Sí", "«Haber» impersonal va en singular."),
   E("¿Qué se hace para detectar la concordancia?", "Subrayar el sujeto y comprobar el verbo", "Se revisa que coincidan.")],
  ("Corrige este borrador de ejemplo y anota qué tipo de error era cada uno: «Nosotros se fuimos al museo. Habían muchos estudiantes. He escribido una nota. Las niñas contento miraron la obra».",
   "Nosotros nos fuimos al museo (reflexivo). Había muchos estudiantes (haber impersonal). He escrito una nota (participio). Las niñas contentas miraron la obra (concordancia).",
   ["corrige los cuatro errores", "identifica el tipo de cada uno"], ["texto corregido y lista de tipos"], ["dejar errores sin corregir"], "Comprueba que no quede ninguno y que el tipo sea el correcto."),
  "Lee un texto tuyo en voz alta y detecta cuando algo «suena raro».",
  "Escribe tres oraciones con participios irregulares.")

# ------------------------------------------------------------------ OA 15 · clase 6
L(OA, 6,
  "Aprenderé a editar y presentar un texto: corregir ortografía y puntuación, mejorar la presentación y usar eficazmente las herramientas del procesador de textos.",
  ["Corrijo gramática y concordancia.", "Uso conectores y vocabulario preciso."],
  ["Editar es la etapa final de la escritura. Se corrigen la ortografía (tildes, uso de letras) y la puntuación (comas, puntos, dos puntos). Algunas reglas útiles: «porque» explica una causa («Voy porque quiero»); «por qué» se usa en preguntas («¿Por qué llegaste tarde?») y en preguntas indirectas («No sé por qué llegó tarde»); «porqué» es un sustantivo («No sé el porqué»). «A ver» expresa mirar o comprobar; «haber» es un verbo («va a haber una fiesta»).",
   "Las tildes diacríticas distinguen palabras: «él» (pronombre) y «el» (artículo); «tú» (pronombre) y «tu» (posesivo); «sí» (afirmación) y «si» (condicional); «más» (cantidad) y «mas» (pero). En la puntuación, se usa coma para enumerar y para separar al interpelado («Compañeros, vengan»), y dos puntos después del saludo formal («Estimada directora:»).",
   "El procesador de textos ayuda: el corrector ortográfico subraya errores, pero no detecta todos, como «a ver» por «haber», porque ambas palabras existen. Buscar y reemplazar cambia un término repetido en todo el documento. Los estilos de título ordenan los apartados y permiten crear un índice. El interlineado y los márgenes mejoran la lectura; la vista previa muestra cómo quedará impreso. Guarda copias con distintos nombres para conservar versiones."],
  [("tilde diacrítica", "tilde que distingue dos palabras que se escriben igual, como él y el"), ("corrector ortográfico", "herramienta que subraya posibles errores de escritura"), ("buscar y reemplazar", "función que cambia una palabra por otra en todo el documento"), ("estilo de título", "formato que marca los apartados de un documento")],
  [("Elegir entre porque y por qué",
    "Completa: «No sé ____ llegó tarde». ¿Es «por qué», «porque» o «porqué»?",
    ["Es una pregunta indirecta.", "En la pregunta indirecta se escribe «por qué», separado y con tilde.", "Es «por qué»."],
    "por qué"),
   ("Detectar lo que el corrector no ve",
    "Oración: «Voy haber qué pasó». El corrector no marca error. ¿Por qué?",
    ["«Haber» es una palabra válida.", "El corrector ve palabras, no sentido.", "Debe ser «a ver»."],
    "Porque «haber» existe, pero debió ser «a ver»; el corrector no revisa el sentido")],
  [("Confiar solo en el corrector ortográfico.", "No detecta errores de sentido.", "Lee el texto completo después de corregir."),
   ("Cambiar una palabra repetida a mano en todo el texto.", "Es lento y se pueden olvidar casos.", "Usa buscar y reemplazar.")],
  ([E("¿«¿Por qué llegaste tarde?» lleva «por qué» o «porque»?", "Por qué", "Es una pregunta."),
    E("¿«Tu» sin tilde es un posesivo: sí o no?", "Sí", "Indica pertenencia, como «tu cuaderno»."),
    E("¿El corrector ortográfico revisa el sentido de las palabras?", "No", "Solo detecta palabras inexistentes o mal escritas.")],
   [E("Completa: «Dijo que ____ puedes venir». A) tú B) tu", "A) tú", "Es el pronombre sujeto."),
    E("Completa: «Voy ____ no hay más remedio». A) porque B) por qué", "A) porque", "Introduce una causa."),
    E("Elige la puntuación correcta. A) «Estimada directora: Solicito la sala.» B) «Estimada directora. solicito la sala.»", "A) «Estimada directora: Solicito la sala.»", "Tras el saludo formal se usan dos puntos y el texto parte con mayúscula; un punto seguido de minúscula es incorrecto.")],
   [E("Clasifica con D (diacrítica correcta) o X (incorrecta): 1) «Él trajo el cuaderno». 2) «Tu eres amable» (con tu como pronombre). 3) «Si, quiero ir» (como afirmación). Escribe las letras en orden.", "D, X, X", "Falta tilde en «tú» y el «sí» afirmativo."),
    E("Quieres cambiar «bonito» por «agradable» en las 12 apariciones de un documento largo. ¿Qué herramienta conviene? A) buscar y reemplazar B) el corrector ortográfico", "A) buscar y reemplazar", "Cambia todas las apariciones de una vez; el corrector solo marca posibles errores."),
    E("Quieres marcar los apartados de un informe de 5 secciones y generar un índice. ¿Qué usas? A) estilos de título B) el color de fondo", "A) estilos de título", "Marcan las secciones.")],
   [E("Un compañero dice: «Mi texto está perfecto, el corrector no marcó nada». ¿Qué le sugieres? A) releerlo atendiendo al sentido, porque el corrector no detecta todo B) entregarlo así, porque el corrector nunca se equivoca", "A) releerlo atendiendo al sentido, porque el corrector no detecta todo", "Palabras como «haber» y «a ver» existen y el corrector no distingue cuál corresponde."),
    E("Un documento de 10 páginas con interlineado muy apretado y márgenes mínimos. ¿Qué mejora la lectura? A) subir el interlineado y ajustar márgenes B) achicar la letra", "A) subir el interlineado y ajustar márgenes", "Facilita la lectura.")],
   [E("Elige la oración correcta. A) «No conozco el porqué de su enojo» B) «No conozco el por qué de su enojo»", "A) «No conozco el porqué de su enojo»", "Después de «el» se usa el sustantivo «porqué», junto y con tilde."),
    E("Elige la frase correcta. A) «Va a haber una reunión» B) «Va a a ver una reunión»", "A) «Va a haber una reunión»", "Aquí «haber» es verbo.")]),
  [E("Párrafo: «Mas tarde, él pregunto por que no vinimos». Las correcciones son más, preguntó y por qué. ¿Cuántas correcciones necesita?", "3", "Hay tres errores.")],
  [E("¿Qué es «buscar y reemplazar»?", "Una función que cambia una palabra en todo el documento", "Ahorra tiempo al editar."),
   E("¿«Porqué» es sustantivo?", "Sí", "Significa el motivo."),
   E("¿Qué se hace al final: editar o planificar?", "Editar", "Es la etapa final.")],
  ("Edita este borrador de ejemplo: «hola estimada directora. Mas tarde nos juntaremos haber si resolvemos el problema, por que tu nos pediste ayuda». Reescríbelo en formato de carta formal, corrige ortografía y puntuación, y explica qué herramienta del procesador usarías.",
   "Estimada directora: Más tarde nos juntaremos a ver si resolvemos el problema, porque usted nos pidió ayuda. Usaría el corrector y luego leería en voz alta para detectar «a ver».",
   ["corrige los errores", "aplica formato de carta", "menciona una herramienta"], ["carta corregida y herramienta"], ["confiar solo en el corrector"], "Lee tu versión final en voz alta para comprobar que no queden errores de sentido."),
  "Revisa la ortografía de un mensaje tuyo.",
  "Escribe tres frases con «porque», «por qué» y «porqué».")
